mapper.select:
select (select keyword.keyword_name from keyword where keyword_no = acm.keyword_no) as keywordName, (select category.category_name from category where category_no = acm.category_no) as categoryName,
acm.accommodation_no as acmNo, acm.accommodation_name as acmName, acm.accommodation_address as acmAddress, acm.accommodation_contents as contents, acm.checkin AS checkinTime, acm.checkout AS checkoutTime, acm.tel AS acmTel,
rm.room_no as roomNo, rm.room_name as roomName, rm.room_qty as roomQty, rm.room_price as roomPrice, rm.room_discount as roomDiscount, rm.room_contents as roomContents, rm.room_viewtype as roomViewtype, rm.room_capacity as roomCapacity from accommodation acm inner join room rm on acm.accommodation_no = rm.accommodation_no where rm.accommodation_no = #{acmNo} and rm.room_no = #{roomNo}

SELECT a.accommodation_no AS acmNo, a.accommodation_name AS acmName, a.accommodation_address AS acmAddress, a.accommodation_contents AS contents, a.checkin AS checkinTime, a.checkout AS checkoutTime, a.tel AS acmTel, a.keyword_no AS keywordNo, a.business_no AS businessNo, a.category_no AS categoryNo FROM accommodation a LEFT JOIN category c ON a.category_no = c.category_no LEFT JOIN keyword k ON a.keyword_no = k.keyword_no WHERE 1=1
AND (a.accommodation_name LIKE CONCAT ('%', #{search}, '%') OR a.tel LIKE CONCAT ('%', #{search}, '%'))
AND a.business_no = #{businessNo} ORDER BY a.accommodation_no DESC LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM accommodation WHERE 1=1
AND (accommodation_name LIKE CONCAT ('%', #{search}, '%') OR tel LIKE CONCAT ('%', #{search}, '%'))
AND business_no = #{businessNo}

SELECT r.room_no as roomNo, r.accommodation_no as acmNo, r.room_name as roomName, r.room_qty as roomQty, r.room_price as roomPrice, r.room_discount as roomDiscount, r.room_contents as roomContents, r.room_viewtype as roomViewType, r.room_capacity as roomCapacity FROM room r JOIN accommodation a ON r.accommodation_no = a.accommodation_no WHERE 1=1
AND r.room_name LIKE CONCAT ('%', #{search}, '%')
AND a.accommodation_no = #{acmNo} ORDER BY r.room_no DESC LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM room WHERE 1=1
AND room_name LIKE CONCAT ('%', #{search}, '%')
AND accommodation_no = #{acmNo}
